const items = $input.all();
const frenchMonthNames = ['Janvier','Février','Mars','Avril','Mai','Juin','Juillet','Août','Septembre','Octobre','Novembre','Décembre'];
const yearGroups = {};

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const text = item.json.text ?? '';
  const internalDate = item.json.internalDate;

  let month = null;
  let year = null;

  // Primary: parse "Salaire versé le : DD/MM/YY" from PDF text
  const salMatch = text.match(/Salaire vers[eé] le\s*:\s*(\d{2})\/(\d{2})\/(\d{2,4})/i);
  if (salMatch) {
    const monthNum = parseInt(salMatch[2]);
    month = frenchMonthNames[monthNum - 1] ?? null;
    const yr = salMatch[3];
    year = yr.length === 2 ? '20' + yr : yr;
  }

  // Fallback: email internal date
  if ((!month || !year) && internalDate) {
    const d = new Date(parseInt(internalDate));
    if (!year) year = d.getFullYear().toString();
    if (!month) month = frenchMonthNames[d.getMonth()];
  }

  year = year || 'unknown';
  const fileName = month ? `${month}_${year}.pdf` : `paystub_${i}.pdf`;

  if (!yearGroups[year]) yearGroups[year] = {};

  const bin = item.binary?.attachment_0;
  if (bin) {
    const idx = Object.keys(yearGroups[year]).length;
    yearGroups[year][`pdf_${idx}`] = { ...bin, fileName };
  }
}

return Object.entries(yearGroups).map(([year, binaryData]) => ({
  json: { year },
  binary: binaryData
}));
